  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Stricter limit for auth endpoint if added
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts
});
```

---

#### 5. **No HTTPS/TLS Configuration** 🔴
**Issue**: Application doesn't enforce or support HTTPS.

**Risk**: Man-in-the-Middle (MITM) attacks, credential interception

**Recommendation**:
```javascript
const https = require('https');
const fs = require('fs');
const express = require('express');

const app = express();

// Redirect HTTP to HTTPS
app.use((req, res, next) => {
  if (req.header('x-forwarded-proto') !== 'https' && process.env.NODE_ENV === 'production') {
    res.redirect(`https://${req.header('host')}${req.url}`);
  } else {
    next();
  }
});

// Start HTTPS server in production
if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH),
  };
  https.createServer(options, app).listen(443);
} else {
  app.listen(3000);
}
```

