### 6. ⚠️ HIGH: No Logging/Monitoring (OWASP A09:2021 – Security Logging and Monitoring Failures)

**Issue:** No security logging for audit trails or anomaly detection.

**Risk:**
- Unable to detect security breaches
- No audit trail for compliance
- Delayed incident response

**Recommendation:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// HTTP request logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  }
}));

// Security event logging
app.use((req, res, next) => {
  res.on('finish', () => {
    if (res.statusCode === 401 || res.statusCode === 403) {
      logger.warn('Unauthorized access attempt', {
        ip: req.ip,
        endpoint: req.path,
        method: req.method,
        statusCode: res.statusCode,
      });
    }
  });
  next();
});

app.get('/users', authenticateToken, (req, res) => {
  logger.info('Users endpoint accessed', {
    userId: req.user.id,
    ip: req.ip,
  });
  // ... endpoint logic
});
```

