    app.listen(3000, () => {
      console.log('Server running on port 3000');
    });
  } catch (error) {
    console.error('Failed to start:', error.message);
    process.exit(1);
  }
}

startApp();
```

---

#### **Option 3: HashiCorp Vault (High-Security)**

```javascript
// config/vault.js - Using Vault for secrets
const axios = require('axios');

async function getVaultSecret(path) {
  const token = process.env.VAULT_TOKEN; // Injected by orchestrator

  try {
    const response = await axios.get(
      `${process.env.VAULT_ADDR}/v1/secret/data/${path}`,
      { headers: { 'X-Vault-Token': token } }
    );

    return response.data.data.data;
  } catch (error) {
    console.error('Vault error:', error.message);
    throw error;
  }
}

module.exports = { getVaultSecret };
```

---

#### **Option 4: Kubernetes Secrets (Container Orchestration)**

```javascript
// config/k8sSecrets.js - Using K8s secrets mounted as files
const fs = require('fs');
const path = require('path');

function loadK8sSecret(secretName) {
  const secretPath = path.join('/var/run/secrets/kubernetes.io/serviceaccount', secretName);

  try {
    return fs.readFileSync(secretPath, 'utf-8').trim();
  } catch (error) {
    console.error(`Failed to load K8s secret ${secretName}:`, error.message);
    throw error;
  }
}

const config = {
  database: {
    url: loadK8sSecret('database-url')
  },
  anthropic: {
    apiKey: loadK8sSecret('anthropic-api-key')
  }
};

module.exports = config;
```

---

### **CRITICAL SECURITY PRACTICES**

#### **1. Never Commit `.env` Files**
```bash
# .gitignore
.env
.env.local
.env.*.local
```

#### **2. Prevent Secrets in Logs**
```javascript
// UNSAFE - DO NOT DO THIS
console.log('Config:', config); // Prints all secrets!

// SAFE
console.log('Database host:', new URL(config.database.url).hostname);
console.log('Using AWS region:', process.env.AWS_REGION);
```

#### **3. Secure Log Redaction**
```javascript
// logger.js - Redact sensitive data
const redactSecrets = (str) => {
  return String(str)
    .replace(/sk[-_].*?\b/g, 'sk-...') // API keys
    .replace(/AKIA[\dA-Z]+/g, 'AKIA...') // AWS access keys
    .replace(/:.*?@/g, ':***@') // Database passwords
    .replace(/".*?":\s*"[^"]*"/, '"***"'); // Generic credentials
};

module.exports = { redactSecrets };
```

#### **4. Secret Rotation**
```javascript
// Automatically refresh secrets periodically
setInterval(async () => {
  try {
    config = await loadSecrets();
    console.log('Secrets rotated successfully');
  } catch (error) {
    console.error('Secret rotation failed:', error.message);
    // App continues with old secrets, but alert ops team
  }
}, 24 * 60 * 60 * 1000); // Every 24 hours
```

#### **5. Audit Trail**
```javascript
// Track who accessed secrets
function accessSecret(name) {
  console.log(`[AUDIT] Secret accessed: ${name} at ${new Date().toISOString()}`);
  // In production: send to audit logging service
  return config[name];
}
```

---

### **SUMMARY OF RISKS & RECOMMENDATIONS**

