  credentials: true,
}));
app.use(express.json({ limit: '10kb' }));
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
}));
app.use(morgan('combined', { stream: { write: (msg) => logger.info(msg) } }));

// Health endpoint (no auth required)
