# Express.js Security Audit Report

**Date:** May 23, 2026  
**Application Type:** Express.js REST API  
**Severity Levels:** Critical, High, Medium, Low

---

## Executive Summary

This Express.js application contains **7 Critical/High severity vulnerabilities** and **multiple medium-severity issues** that violate OWASP Top 10 guidelines. The application lacks essential security controls including authentication, input validation, rate limiting, and proper HTTP security headers. Immediate remediation is required before production deployment.

**Overall Risk Rating:** CRITICAL

---

## Detailed Vulnerability Analysis

### 1. OWASP A01:2021 - Broken Access Control

#### Finding 1.1: Missing Authentication & Authorization
**Severity:** CRITICAL  
**CWE:** CWE-306 (Missing Authentication for Critical Function)

**Vulnerability Description:**
All endpoints are publicly accessible without any authentication mechanism. There is no verification that users are who they claim to be.

```javascript
// VULNERABLE: No authentication required
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Risk:**
- Unauthorized access to sensitive user data
- Exposed PII (personally identifiable information)
- Complete bypass of intended access controls

**Remediation:**

```javascript
const jwt = require('jsonwebtoken');

// Middleware for authentication
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Verify user has permission to view users
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 2. OWASP A02:2021 - Cryptographic Failures

#### Finding 2.1: Sensitive Data Exposure
**Severity:** CRITICAL  
**CWE:** CWE-200 (Exposure of Sensitive Information)

**Vulnerability Description:**
Email addresses (PII) are returned in plaintext via HTTP without encryption. The application doesn't enforce HTTPS.

**Risk:**
- Sensitive user information exposed to man-in-the-middle attacks
- Email addresses can be harvested for phishing campaigns
- Violates GDPR/data protection regulations

**Remediation:**

```javascript
const express = require('express');
const helmet = require('helmet');
const app = express();

// 1. Enforce HTTPS
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(`https://${req.headers.host}${req.url}`);
  }
  next();
});

// 2. Add security headers
app.use(helmet());

// 3. Configure CSP
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
  },
}));

// 4. Configure HSTS
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true,
}));

// 5. Don't expose sensitive data unnecessarily
app.get('/users', authenticateToken, (req, res) => {
  // Only return necessary fields
  const users = [
    { id: 1, name: 'Alice' }, // Remove email from response
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});
```

**HTTPS Configuration (nginx reverse proxy example):**
```nginx
server {
    listen 443 ssl http2;
    server_name api.example.com;

    ssl_certificate /path/to/cert.pem;
    ssl_certificate_key /path/to/key.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers 'ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256';
}
```

---

### 3. OWASP A03:2021 - Injection

#### Finding 3.1: No Input Validation
**Severity:** HIGH  
**CWE:** CWE-20 (Improper Input Validation)

**Vulnerability Description:**
The application doesn't validate any input parameters. If query parameters were used (e.g., filtering, pagination), SQL injection, NoSQL injection, or command injection attacks would be possible.

**Risk Example - Potential attack vectors:**
```bash
# SQL Injection example (if /users?name=X endpoint existed)
GET /users?name='; DROP TABLE users; --

# NoSQL Injection
GET /users?id={"$gt": ""}

# Command Injection (if system commands were used)
GET /search?query=; rm -rf /
```

**Remediation:**

```javascript
const { query, validationResult, body } = require('express-validator');

// Input validation middleware
const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1, max: 999999 })
    .withMessage('Invalid user ID'),
  query('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Invalid name format'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
];

app.get('/users', 
  authenticateToken, 
  validateUserQuery,
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { id, name, limit = 10 } = req.query;

    // Use parameterized queries if using database
    let users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    if (id) {
      users = users.filter(u => u.id === parseInt(id));
    }
    if (name) {
      users = users.filter(u => u.name.toLowerCase().includes(name.toLowerCase()));
    }

    res.json(users.slice(0, limit));
  }
);
```

---

### 4. OWASP A05:2021 - Access Control (CORS & CSRF)

#### Finding 4.1: Missing CORS Configuration
**Severity:** MEDIUM  
**CWE:** CWE-346 (Origin Validation Error)

**Vulnerability Description:**
No CORS (Cross-Origin Resource Sharing) policy is configured, making the API vulnerable to unauthorized cross-origin requests.

**Remediation:**

```javascript
const cors = require('cors');

// Strict CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
};

app.use(cors(corsOptions));

// Prevent CSRF attacks
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});
```

---

### 5. OWASP A06:2021 - Vulnerable & Outdated Components

#### Finding 5.1: No Dependency Management
**Severity:** HIGH  
**CWE:** CWE-1035 (Vulnerable Third-Party Component)

**Vulnerability Description:**
The application doesn't specify dependency versions or use lock files, making it vulnerable to:
- Known vulnerabilities in transitive dependencies
- Unexpected breaking changes
- Supply chain attacks

**Remediation:**

**package.json:**
```json
{
  "name": "secure-api",
  "version": "1.0.0",
  "description": "Secure Express.js API",
  "main": "index.js",
  "scripts": {
    "start": "node index.js",
    "dev": "nodemon index.js",
    "audit": "npm audit",
    "audit:fix": "npm audit fix"
  },
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "express-validator": "^7.0.0",
    "jsonwebtoken": "^9.0.0",
    "cors": "^2.8.5",
    "dotenv": "^16.0.3",
    "hpp": "^0.2.3",
    "express-rate-limit": "^6.7.0"
  },
  "devDependencies": {
    "nodemon": "^2.0.22"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
```

**Commands:**
```bash
# Check for vulnerabilities
npm audit

# Fix known vulnerabilities
npm audit fix

# Use npm ci instead of npm install in production
npm ci --omit=dev
```

---

### 6. OWASP A07:2021 - Identification & Authentication Failures

#### Finding 6.1: No Session Management
**Severity:** HIGH  
**CWE:** CWE-384 (Session Fixation)

**Vulnerability Description:**
No session management, rate limiting on authentication endpoints, or token expiration strategy.

**Risk:**
- Brute force attacks on login endpoints
- Token replay attacks
- Session hijacking

**Remediation:**

```javascript
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');

// Rate limiting for login attempts
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 requests per windowMs
  message: 'Too many login attempts, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

// Token refresh endpoint with rate limiting
app.post('/auth/login', loginLimiter, (req, res) => {
  // Validate credentials
  const user = { id: 1, username: 'alice', role: 'admin' };

  // Generate tokens with expiration
  const accessToken = jwt.sign(
    { id: user.id, username: user.username, role: user.role },
    process.env.JWT_SECRET,
    { expiresIn: '15m' } // Short-lived access token
  );

  const refreshToken = jwt.sign(
    { id: user.id },
    process.env.JWT_REFRESH_SECRET,
    { expiresIn: '7d' } // Longer-lived refresh token
  );

  // Store refresh token in secure, httpOnly cookie
  res.cookie('refreshToken', refreshToken, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
  });

  res.json({
    accessToken,
    expiresIn: 900, // 15 minutes in seconds
  });
});

app.post('/auth/refresh', (req, res) => {
  const token = req.cookies.refreshToken;

  if (!token) {
    return res.status(401).json({ error: 'Refresh token required' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_REFRESH_SECRET);
    const newAccessToken = jwt.sign(
      { id: decoded.id },
      process.env.JWT_SECRET,
      { expiresIn: '15m' }
    );
    res.json({ accessToken: newAccessToken });
  } catch (err) {
    res.status(403).json({ error: 'Invalid refresh token' });
  }
});
```

---

### 7. OWASP A09:2021 - Logging & Monitoring Failures

#### Finding 7.1: No Logging or Monitoring
**Severity:** HIGH  
**CWE:** CWE-778 (Insufficient Logging)

**Vulnerability Description:**
No security event logging. Cannot detect or investigate:
- Unauthorized access attempts
- Suspicious API usage patterns
- Security incidents

**Remediation:**

```javascript
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// Create logs directory
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir);
}

// Configure Morgan for HTTP request logging
const accessLogStream = fs.createWriteStream(
  path.join(logsDir, 'access.log'),
  { flags: 'a' }
);

// Custom Morgan format for security logging
morgan.token('user-id', (req) => req.user?.id || 'anonymous');

app.use(morgan(':remote-addr - :user-id [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" ":user-agent"', {
  stream: accessLogStream,
}));

// Security event logger
const securityLogger = {
  log: (level, event, details) => {
    const timestamp = new Date().toISOString();
    const logEntry = {
      timestamp,
      level,
      event,
      ...details,
    };
    console.error(JSON.stringify(logEntry));
    fs.appendFileSync(
      path.join(logsDir, 'security.log'),
      JSON.stringify(logEntry) + '\n'
    );
  },
};

// Log failed authentication attempts
app.use((err, req, res, next) => {
  if (err.status === 401 || err.status === 403) {
    securityLogger.log('WARN', 'AUTH_FAILURE', {
      ip: req.ip,
      path: req.path,
      method: req.method,
      userAgent: req.get('user-agent'),
    });
  }
  next(err);
});
```

---

### 8. Missing Security Headers & Middleware

#### Finding 8.1: No Security Headers
**Severity:** MEDIUM  
**CWE:** CWE-693 (Protection Mechanism Failure)

**Vulnerability Description:**
Missing critical HTTP security headers that prevent common attacks (XSS, clickjacking, etc.)

**Remediation:**

```javascript
const helmet = require('helmet');

// Apply all Helmet protections
app.use(helmet());

// Specific header configurations
app.use(helmet.frameguard({ action: 'deny' })); // X-Frame-Options: DENY
app.use(helmet.xssFilter()); // X-XSS-Protection: 1; mode=block
app.use(helmet.noSniff()); // X-Content-Type-Options: nosniff
app.use(helmet.hidePoweredBy()); // Remove X-Powered-By header

// Custom security headers
app.use((req, res, next) => {
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
});
```

---

### 9. Error Handling & Information Disclosure

#### Finding 9.1: Improper Error Handling
**Severity:** MEDIUM  
**CWE:** CWE-209 (Information Exposure Through Error Message)

**Vulnerability Description:**
Unhandled errors may expose sensitive information like stack traces and system details.

```javascript
// VULNERABLE: Exposes stack trace
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (err) {
    res.status(500).json({ error: err.message, stack: err.stack }); // DANGER!
  }
});
```

**Remediation:**

```javascript
// Global error handling middleware
app.use((err, req, res, next) => {
  // Log full error details server-side
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Never expose internal details to client
  const statusCode = err.status || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    error: isProduction 
      ? 'Internal server error' 
      : err.message,
    ...(process.env.NODE_ENV === 'development' && { 
      stack: err.stack 
    }),
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global uncaught exception handler
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});
```

---

### 10. Missing Request Size Limits & Body Parser

#### Finding 10.1: No Request Size Restrictions
**Severity:** MEDIUM  
**CWE:** CWE-400 (Uncontrolled Resource Consumption)

**Vulnerability Description:**
Large payloads can cause denial-of-service (DoS) attacks consuming server resources.

**Remediation:**

```javascript
const express = require('express');
const helmet = require('helmet');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

const app = express();

// Limit request payload sizes
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Prevent HTTP parameter pollution
app.use(hpp());

// Rate limiting (general API rate limit)
const generalLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100, // 100 requests per minute
  message: 'Too many requests from this IP',
});

app.use(generalLimiter);
```

---

## Complete Secure Implementation Example

```javascript
require('dotenv').config();
const express = require('express');
