### SECURE CODE

```javascript
const express = require('express');
const helmet = require('helmet');
const app = express();

// Enforce HTTPS
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(301, `https://${req.headers.host}${req.url}`);
  }
  next();
});

// Add security headers with Helmet
app.use(helmet());
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true,
}));

// Only transmit necessary data, encrypted
app.get('/api/user/profile', authenticateToken, (req, res) => {
  res.json({
    name: 'Alice',
    email: 'alice@example.com',
    // SSN and bank account NOT returned
  });
});

app.listen(3000);
```

**nginx Configuration for HTTPS:**
```nginx
server {
    listen 443 ssl http2;
    server_name api.example.com;

    ssl_certificate /path/to/cert.pem;
    ssl_certificate_key /path/to/key.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;

    # Redirect HTTP to HTTPS
    if ($scheme != "https") {
        return 301 https://$server_name$request_uri;
    }

    # Security headers
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
    add_header X-Frame-Options "DENY" always;
    add_header X-Content-Type-Options "nosniff" always;

    location / {
        proxy_pass http://localhost:3000;
    }
}
```

**Protections:**
- All traffic encrypted via HTTPS/TLS
- HSTS enforces HTTPS
- Security headers prevent attacks
- Sensitive data removed from responses
- Protected against MITM attacks

