### SECURE CODE

```javascript
const { query, body, validationResult } = require('express-validator');

// Define validation rules
const validateSearch = [
  query('query')
    .trim()
    .isLength({ min: 1, max: 100 })
    .matches(/^[a-zA-Z0-9\s'-]+$/)
    .withMessage('Invalid query format'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be 1-100'),
  query('sort')
    .optional()
    .isIn(['name', 'date', 'relevance'])
    .withMessage('Invalid sort field'),
];

const validateUserCreation = [
  body('username')
    .trim()
    .isLength({ min: 3, max: 50 })
    .matches(/^[a-zA-Z0-9_-]+$/)
    .withMessage('Invalid username'),
  body('age')
    .isInt({ min: 18, max: 150 })
    .toInt()
    .withMessage('Age must be 18-150'),
];

// Search endpoint with validation
app.get('/search', validateSearch, (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { query, limit = 10, sort = 'name' } = req.query;

  // Use parameterized queries (if using database)
  // SECURE: Parameter is passed separately
  const results = database.query(
    'SELECT * FROM users WHERE name LIKE ? LIMIT ? ORDER BY ?',
    [`%${query}%`, limit, sort]
  );

  res.json(results);
});

// User creation endpoint with validation
app.post('/user', validateUserCreation, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { username, age } = req.body;

  // SECURE: Validated data only
  database.insert('users', { username, age });

  res.json({ success: true });
});
```

**Protections:**
- All input validated before use
- Type checking enforced
- Length limits applied
- Format validation with regex
- SQL injection prevented
- NoSQL injection prevented
- XSS prevented
- 400 Bad Request for invalid input

