---

### SECURE CODE

```javascript
app.get('/users/:id', (req, res) => {
  try {
    const userId = req.params.id;
    const user = database.findUser(userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (err) {
    // Log full error server-side only
    console.error('Database error:', {
      message: err.message,
      stack: err.stack,
      sql: err.sql,
      userId: req.params.id,
      timestamp: new Date().toISOString(),
    });

    // Return generic error to client
    const statusCode = err.status || 500;
    const isProduction = process.env.NODE_ENV === 'production';

    res.status(statusCode).json({
      error: isProduction
        ? 'Internal server error'
        : err.message,
      code: 'INTERNAL_ERROR',
      requestId: req.id, // For tracing
    });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error with context
  console.error('Unhandled error:', {
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Generic response
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message,
  });
});
```

**Error Response (Secure - Production):**
```json
{
  "error": "Internal server error",
  "code": "INTERNAL_ERROR",
  "requestId": "req_abc123"
}
```

**Error Response (Secure - Development):**
```json
{
  "error": "Unknown column 'users.wrongcolumn' in 'field list'",
  "code": "INTERNAL_ERROR",
  "requestId": "req_abc123"
}
```

**Protections:**
- Stack traces hidden in production
- Database details not exposed
- Generic error messages shown
- Full errors logged server-side
- Request tracking ID for support
- No SQL queries visible
- Internal code logic protected

