  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Filter sensitive data
  const sanitized = users.map(u => ({
    id: u.id,
    name: u.name,
    ...(req.user.role === 'admin' && { email: u.email })
  }));

  res.json(sanitized);
});

// 404 handler
