  logger.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    ip: req.ip,
    error: err.message
  });
  res.status(500).json({ error: 'Internal server error' });
});

// ===== SERVER STARTUP =====

