    "audit": "npm audit --production",
    "audit-fix": "npm audit fix"
  }
}
```

---

### A07:2021 - Identification and Authentication Failures

**Current Risk: CRITICAL**

**Vulnerabilities:**
- No user identification mechanism
- No session tracking
- No account lockout after failed attempts

**Secure Implementation:**
```javascript
const session = require('express-session');
const RedisStore = require('connect-redis').default;

// Session configuration
app.use(session({
  store: new RedisStore({ client: redisClient }),
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { 
    secure: true, // HTTPS only
    httpOnly: true,
    sameSite: 'strict',
    maxAge: 1000 * 60 * 60 // 1 hour
  }
}));

// Account lockout mechanism
const failedLoginAttempts = new Map();

const checkAccountLockout = (username) => {
  const attempts = failedLoginAttempts.get(username) || { count: 0, lockedUntil: 0 };

  if (Date.now() < attempts.lockedUntil) {
    return true; // Account is locked
  }

  return false;
};

const recordFailedLogin = (username) => {
  const attempts = failedLoginAttempts.get(username) || { count: 0, lockedUntil: 0 };
  attempts.count++;

  if (attempts.count >= 5) {
    attempts.lockedUntil = Date.now() + (15 * 60 * 1000); // Lock for 15 minutes
  }

  failedLoginAttempts.set(username, attempts);
};
```

---

### A08:2021 - Software and Data Integrity Failures

**Current Risk: MEDIUM**

**Vulnerabilities:**
- No integrity verification
- No audit logging
- No data validation on input

**Secure Implementation:**
```javascript
const crypto = require('crypto');

// Audit logging
const auditLog = (action, user, details) => {
  const timestamp = new Date().toISOString();
  const logEntry = JSON.stringify({
    timestamp,
    action,
    userId: user?.id,
    username: user?.username,
    details,
    ipAddress: req.ip,
  });

  console.log(logEntry);
  // Store in secure logging system
};

// Data integrity check
const calculateDataHash = (data) => {
  return crypto
    .createHash('sha256')
    .update(JSON.stringify(data))
    .digest('hex');
};

app.get('/users/:id', authenticateToken, (req, res) => {
  const user = users.find(u => u.id === parseInt(req.params.id));

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Log the access
  auditLog('USER_READ', req.user, { userId: user.id });

  // Add integrity hash
  const dataHash = calculateDataHash(user);
  res.set('X-Data-Integrity', dataHash);

  res.json(user);
});
```

---

### A09:2021 - Logging and Monitoring Failures

**Current Risk: HIGH**

**Vulnerabilities:**
- No logging implemented
- No monitoring or alerting
- No security event tracking

**Secure Implementation:**
```javascript
const winston = require('winston');

// Logging configuration
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'express-app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Security event logging middleware
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    const logData = {
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    };

    if (res.statusCode >= 400) {
      logger.warn('HTTP Error', logData);
    } else {
      logger.info('HTTP Request', logData);
    }
  });

  next();
});

// Monitor for suspicious patterns
app.use((err, req, res, next) => {
  logger.error('Application Error', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't expose error details to client
  res.status(500).json({ error: 'Internal server error' });
});
```

---

### A10:2021 - Server-Side Request Forgery (SSRF)

**Current Risk: MEDIUM** (if application expands to make external requests)

**Vulnerabilities:**
- Not immediately applicable to this app, but risk if it makes external HTTP calls

**Secure Implementation:**
```javascript
const axios = require('axios');
const { URL } = require('url');

// Whitelist of allowed domains
const ALLOWED_DOMAINS = ['api.example.com', 'trusted-service.com'];

const isAllowedURL = (urlString) => {
  try {
    const url = new URL(urlString);

    // Prevent local network access
    const hostname = url.hostname;
    if (hostname === 'localhost' || hostname === '127.0.0.1' || hostname.startsWith('192.168.') || hostname.startsWith('10.')) {
      return false;
    }

    // Whitelist check
    return ALLOWED_DOMAINS.some(domain => hostname.endsWith(domain));
  } catch {
    return false;
  }
};

app.get('/proxy', authenticateToken, async (req, res) => {
  const { url } = req.query;

  if (!url) {
    return res.status(400).json({ error: 'URL parameter required' });
  }

  if (!isAllowedURL(url)) {
    logger.warn('SSRF attempt blocked', { url, userId: req.user.id });
    return res.status(403).json({ error: 'URL not allowed' });
  }

  try {
    const response = await axios.get(url, { timeout: 5000 });
    res.json(response.data);
  } catch (error) {
    logger.error('Proxy request failed', { url, error: error.message });
    res.status(502).json({ error: 'Failed to fetch URL' });
  }
});
```

---

## 2. Authentication & Authorization Issues

### Current Problems:
1. **No authentication** - Anyone can access all endpoints
2. **No authorization** - No role-based access control (RBAC)
3. **No session management** - No way to track logged-in users
4. **Exposed sensitive data** - Email addresses visible to unauthorized users

### Secure Implementation:

```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');

const app = express();
app.use(helmet());
app.use(express.json());

// Middleware: Authentication
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (error) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

// Middleware: Authorization
const authorize = (allowedRoles) => {
  return (req, res, next) => {
    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// Health check (public)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint (protected)
app.get('/users', authenticate, authorize(['admin', 'user']), (req, res) => {
  // Only return non-sensitive data
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// Admin-only endpoint
app.get('/admin/users', authenticate, authorize(['admin']), (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
  ]);
});

module.exports = app;
```

---

## 3. Input Validation Gaps

### Current Problems:
1. No validation on path parameters
2. No validation on query parameters
3. No validation on request body
4. No sanitization of user input

### Secure Implementation:

```javascript
const { query, param, body, validationResult } = require('express-validator');

// Validation middleware
const validateGetUser = [
  param('id').isInt({ min: 1 }).toInt(),
];

const validateCreateUser = [
  body('name').trim().isLength({ min: 2, max: 100 }).notEmpty(),
  body('email').isEmail().normalizeEmail(),
  body('age').optional().isInt({ min: 0, max: 150 }).toInt(),
];

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array() 
    });
  }
  next();
};

app.get('/users/:id', 
  authenticate,
  validateGetUser,
  handleValidationErrors,
  (req, res) => {
    const { id } = req.params;
    // Safe to use id
    res.json({ id, name: 'User' });
  }
);

app.post('/users',
  authenticate,
  authorize(['admin']),
  validateCreateUser,
  handleValidationErrors,
  (req, res) => {
    const { name, email, age } = req.body;
    // All inputs are validated and sanitized
    res.status(201).json({ id: 3, name, email, age });
  }
);
```

---

## 4. Injection Vulnerability Risks

### Current Problems:
1. Query parameters not validated
2. Potential for NoSQL injection
3. Potential for command injection if system calls are made
4. Potential for template injection

### Secure Implementation:

```javascript
const { query, validationResult } = require('express-validator');

// Safe query building
app.get('/users/search', authenticate, [
  query('q').trim().isLength({ max: 100 }).escape(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { q, limit = 10 } = req.query;

  // Use parameterized queries with database
  // Example with MongoDB:
  // const users = await User.find({ name: { $regex: q, $options: 'i' } }).limit(limit);

  // Example with SQL:
  // const query = 'SELECT * FROM users WHERE name LIKE ? LIMIT ?';
  // const users = await db.query(query, [`%${q}%`, limit]);

  res.json([]);
});

// Safe file operations
const fs = require('fs').promises;
const path = require('path');

app.get('/file/:filename', authenticate, [
  param('filename').matches(/^[\w\-\.]+$/)
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const filename = req.params.filename;
  const filepath = path.join('/safe/directory', filename);

  try {
    const content = await fs.readFile(filepath, 'utf8');
    res.send(content);
  } catch (error) {
    res.status(404).json({ error: 'File not found' });
  }
});
```

---

## 5. Other Security Concerns

### A. Missing Security Headers

**Current Problems:**
- No X-Frame-Options (Clickjacking risk)
- No X-Content-Type-Options (MIME type sniffing)
- No Content-Security-Policy
- No X-XSS-Protection

**Secure Implementation:**
```javascript
const helmet = require('helmet');

// Use helmet for comprehensive header protection
app.use(helmet());

// Custom header configuration
app.use((req, res, next) => {
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  res.setHeader(
    'Content-Security-Policy',
    "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'"
  );
  next();
});
```

### B. CORS Configuration

**Current Problems:**
- No CORS configuration (wide open to all origins)

**Secure Implementation:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 600
}));
```

### C. Error Handling

**Current Problems:**
- Generic error messages could leak information
- Stack traces exposed to users

**Secure Implementation:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';

  logger.error('Unhandled error', {
    message: err.message,
    stack: err.stack,
    path: req.path,
  });

  const statusCode = err.statusCode || 500;
  const response = {
    error: isDevelopment ? err.message : 'Internal server error',
  };

  // Don't expose stack trace in production
  if (isDevelopment) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

### D. Environment Configuration

**Current Problems:**
- No environment variable management
- Secrets might be exposed

**Secure Implementation (.env):**
```
NODE_ENV=production
PORT=3000
JWT_SECRET=your-secret-key-min-32-chars
SESSION_SECRET=your-session-secret
DATABASE_URL=postgresql://user:pass@host/db
LOG_LEVEL=info
ALLOWED_ORIGINS=https://example.com,https://app.example.com
```

**Usage:**
```javascript
require('dotenv').config();

const port = process.env.PORT || 3000;
const jwtSecret = process.env.JWT_SECRET;

if (!jwtSecret) {
  console.error('JWT_SECRET not set. Exiting.');
  process.exit(1);
}
```

### E. HTTPS/TLS Configuration

**Current Problems:**
- No HTTPS enforced
- No HSTS header

**Secure Implementation:**
```javascript
const https = require('https');
const fs = require('fs');

// Enforce HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(`https://${req.header('host')}${req.url}`);
    }
    next();
  });
}

// HSTS
app.use((req, res, next) => {
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');
  next();
});

// Use HTTPS in production
if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH),
  };
  https.createServer(options, app).listen(443);
} else {
