## A03:2021 - Injection

### VULNERABLE CODE
```javascript
// SQL Injection
app.get('/search', (req, res) => {
  const { query } = req.query;
  const sql = `SELECT * FROM users WHERE name LIKE '%${query}%'`;
  db.query(sql, (err, results) => {
    res.json(results);
  });
});

// NoSQL Injection
app.get('/user/:id', (req, res) => {
  const { id } = req.params;
  User.findOne({ _id: id }, (err, user) => {
    res.json(user);
  });
});
```

**Attack Examples:**
```bash
# SQL Injection
GET /search?query='; DROP TABLE users; --
# Executes: SELECT * FROM users WHERE name LIKE ''; DROP TABLE users; --'

# NoSQL Injection
GET /user/{"$ne": null}
# Returns all users instead of filtering

# Command Injection (if exec used)
GET /search?query=`; rm -rf /`
```

### SECURE CODE
```javascript
const { query, param, validationResult } = require('express-validator');

// SQL Injection Prevention
app.get('/search', [
  query('query')
    .trim()
    .notEmpty()
    .isLength({ max: 100 })
    .matches(/^[a-zA-Z0-9\s]+$/) // Whitelist allowed chars
    .escape(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { query } = req.query;
  // Use parameterized query
  const sql = 'SELECT * FROM users WHERE name LIKE ?';
  db.query(sql, [`%${query}%`], (err, results) => {
    res.json(results);
  });
});

// NoSQL Injection Prevention
app.get('/user/:id', [
  param('id')
    .isInt({ min: 1 })
    .toInt(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { id } = req.params;
  // Type-safe query
  User.findOne({ _id: id }, (err, user) => {
    if (!user) return res.status(404).json({ error: 'Not found' });
    res.json(user);
  });
});
```

**Benefits:**
- Input validation prevents injection
- Parameterized queries prevent SQL injection
- Type checking prevents NoSQL injection
- Whitelist approach limits allowed characters

