### SECURE CODE
```javascript
const rateLimit = require('express-rate-limit');

// Account lockout mechanism
const failedAttempts = new Map();

const checkAccountLockout = (username) => {
  const data = failedAttempts.get(username) || { count: 0, lockedUntil: 0 };

  if (Date.now() < data.lockedUntil) {
    return true; // Account locked
  }

  if (data.count >= 5) {
    data.lockedUntil = Date.now() + (15 * 60 * 1000);
  }

  failedAttempts.set(username, data);
  return false;
