### SECURE CODE
```javascript
const crypto = require('crypto');
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'audit.log' }),
  ],
});

// Audit logging
const auditLog = (action, userId, details) => {
  logger.info('Audit event', {
    timestamp: new Date().toISOString(),
    action,
    userId,
    details,
  });
};

// Data integrity hash
const calculateHash = (data) => {
  return crypto
    .createHash('sha256')
    .update(JSON.stringify(data))
    .digest('hex');
};

app.delete('/users/:id', authenticate, authorize(['admin']), (req, res) => {
  const user = User.findById(req.params.id);

  if (!user) {
    return res.status(404).json({ error: 'Not found' });
  }

  // Audit log the deletion
  auditLog('USER_DELETE', req.user.id, {
    deletedUserId: req.params.id,
    deletedUser: user.email,
  });

  User.deleteOne({ _id: req.params.id });
  res.json({ deleted: true });
});

app.put('/users/:id', authenticate, [
  body('name').optional().trim().notEmpty(),
  body('email').optional().isEmail(),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Only allow specific fields
  const allowedFields = ['name', 'email'];
  const update = {};

  allowedFields.forEach(field => {
    if (req.body[field] !== undefined) {
      update[field] = req.body[field];
    }
  });

  const updatedUser = User.findByIdAndUpdate(
    req.params.id,
    update,
    { new: true }
  );

  // Audit log the modification
  auditLog('USER_UPDATE', req.user.id, {
    updatedUserId: req.params.id,
    changes: update,
  });

  res.json(updatedUser);
});

app.get('/data', authenticate, (req, res) => {
  const data = sensitiveData;
  const hash = calculateHash(data);

  res.set('X-Data-Integrity', hash);
  res.json(data);
});
```

**Benefits:**
