// Attack: Access internal services
GET /proxy?url=http://localhost:9200 // Elasticsearch
GET /proxy?url=http://169.254.169.254 // AWS metadata
GET /proxy?url=http://admin.internal // Internal admin
```

### SECURE CODE
```javascript
const axios = require('axios');
const { URL } = require('url');

// Whitelist of allowed domains
const ALLOWED_DOMAINS = [
  'api.example.com',
  'trusted-service.com',
];

const isAllowedURL = (urlString) => {
  try {
    const url = new URL(urlString);

    // Prevent local network access
    const hostname = url.hostname;

    const blockList = [
      'localhost',
      '127.0.0.1',
      '0.0.0.0',
      '169.254.169.254', // AWS metadata
      'metadata.google.internal', // GCP metadata
    ];

    if (blockList.some(blocked => 
      hostname.includes(blocked) || hostname === blocked
    )) {
      return false;
    }

    // Block private IP ranges
    if (/^(192\.168|10\.|172\.1[6-9]\.|172\.2[0-9]\.|172\.3[0-1]\.)/.test(hostname)) {
      return false;
    }

    // Whitelist check
    return ALLOWED_DOMAINS.some(domain => 
      hostname.endsWith(domain)
    );
  } catch {
    return false;
  }
};

app.get('/proxy', authenticate, async (req, res) => {
  const { url } = req.query;

  if (!url) {
    return res.status(400).json({ error: 'URL required' });
  }

  if (!isAllowedURL(url)) {
    logger.warn('SSRF attempt blocked', { 
      url, 
      userId: req.user.id,
      ip: req.ip,
    });
    return res.status(403).json({ error: 'URL not allowed' });
  }

  try {
    const response = await axios.get(url, {
      timeout: 5000, // 5 second timeout
      maxRedirects: 0, // No redirects
    });

    res.json(response.data);
  } catch (error) {
    logger.error('Proxy request failed', {
      url,
      error: error.message,
    });
    res.status(502).json({ error: 'Failed to fetch' });
  }
});
```

**Benefits:**
- Whitelist of allowed domains
- Blocks local network access
- Blocks cloud metadata endpoints
- Timeout prevents hanging requests
- Disables redirects to prevent bypass

