app.get('/users/:id', authenticateToken, (req, res) => {
  const id = parseInt(req.params.id, 10);

  // Validate input
  if (isNaN(id) || id <= 0) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  // Use parameterized queries
  db.query('SELECT * FROM users WHERE id = ?', [id], (err, results) => {
    if (err) return res.status(500).json({ error: 'Database error' });
    if (!results.length) return res.status(404).json({ error: 'User not found' });
    res.json(results[0]);
  });
});
```

---

### 3. ⚠️ A05 - Broken Authentication
**Risk Level:** HIGH
**Issues:**
- No authentication mechanism whatsoever
- No password storage or hashing
- No session management
- No rate limiting on endpoints
- No brute-force protection

**Recommendation:**
```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const rateLimit = require('express-rate-limit');

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

app.use(limiter);

// Login endpoint with proper authentication
app.post('/login', limiter, async (req, res) => {
  // Validate input
  if (!req.body.username || !req.body.password) {
    return res.status(400).json({ error: 'Username and password required' });
  }

  // Verify credentials against database (use bcrypt for password comparison)
  const user = await getUserFromDB(req.body.username);
  if (!user || !await bcrypt.compare(req.body.password, user.passwordHash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Generate JWT token
  const token = jwt.sign({ id: user.id, username: user.username }, 
    process.env.JWT_SECRET, 
    { expiresIn: '1h' }
  );

  res.json({ token });
});
```

---

### 4. ⚠️ A06 - Vulnerable & Outdated Components
**Risk Level:** MEDIUM
**Issues:**
- No `package.json` visible, but dependencies should be kept updated
- Consider using `npm audit` regularly

**Recommendation:**
```bash
# Check for vulnerabilities
npm audit

# Fix vulnerabilities
npm audit fix

# Update dependencies safely
npm outdated
npm update
```

---

### 5. ⚠️ A07 - Identification & Authentication Failures
**Risk Level:** MEDIUM
**Issues:**
- No logging of authentication attempts
- No detection of multiple failed login attempts
- No account lockout mechanism

**Recommendation:**
```javascript
const failedAttempts = {}; // Use Redis in production

app.post('/login', async (req, res) => {
  const username = req.body.username;

  // Check failed attempts
  if (failedAttempts[username] >= 5) {
    return res.status(429).json({ error: 'Account temporarily locked' });
  }

  // Verify credentials
  const user = await getUserFromDB(username);
  if (!user || !await bcrypt.compare(req.body.password, user.passwordHash)) {
    failedAttempts[username] = (failedAttempts[username] || 0) + 1;

    // Log failed attempt
    logger.warn(`Failed login attempt for user: ${username}`);

    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Clear failed attempts on successful login
  delete failedAttempts[username];

  // Log successful login
  logger.info(`User logged in: ${username}`);

  const token = jwt.sign({ id: user.id }, process.env.JWT_SECRET, { expiresIn: '1h' });
  res.json({ token });
});
```

---

### 6. ⚠️ A09 - Security Logging & Monitoring
**Risk Level:** HIGH
**Issues:**
- No error handling with sensitive information exposure
- No security event logging
- No audit trails
- Errors might expose stack traces

**Current Code:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');  // Only console.log
});
```

**Recommendation:**
```javascript
const winston = require('winston');

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Error handling middleware
app.use((err, req, res, next) => {
  logger.error({
    timestamp: new Date().toISOString(),
    endpoint: req.path,
    method: req.method,
    statusCode: err.statusCode || 500,
    error: err.message
  });

  // Don't expose sensitive details to client
  res.status(err.statusCode || 500).json({
    error: 'An error occurred',
    requestId: req.id // Use unique request IDs for tracking
  });
});

app.listen(3000, () => {
  logger.info('Server running on port 3000');
});
```

---

## Missing Security Headers

### ⚠️ No HTTP Security Headers
**Risk Level:** MEDIUM

**Current Issue:** No security headers configured

**Recommendation:**
```javascript
const helmet = require('helmet');
const cors = require('cors');

// Add security headers
app.use(helmet());

// Configure CORS properly
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});
```

---

## Input Validation & Data Validation

### ⚠️ A02 - Cryptographic Failures
**Risk Level:** CRITICAL

**Issues:**
- No HTTPS enforcement (should use SSL/TLS in production)
- No data encryption at rest
- Sensitive data exposed in responses

**Recommendation:**
```javascript
const https = require('https');
const fs = require('fs');

const options = {
  key: fs.readFileSync('path/to/private-key.pem'),
  cert: fs.readFileSync('path/to/certificate.pem')
};

// Use HTTPS in production
if (process.env.NODE_ENV === 'production') {
  https.createServer(options, app).listen(3000);
} else {
  app.listen(3000);
}

// Redirect HTTP to HTTPS
app.use((req, res, next) => {
  if (req.header('x-forwarded-proto') !== 'https' && process.env.NODE_ENV === 'production') {
    res.redirect(`https://${req.header('host')}${req.url}`);
  }
  next();
});
```

