# Security Review of app.js

**Date:** 2026-05-23  
**File:** app.js  
**Risk Level:** MEDIUM

---

## Executive Summary

The application contains several security vulnerabilities and missing hardening measures that should be addressed before production deployment. While the current endpoints are relatively simple, the application lacks essential security controls, input validation, and proper HTTP hardening.

---

## Vulnerabilities Identified

### 1. **MISSING AUTHENTICATION & AUTHORIZATION** ⚠️ CRITICAL
**OWASP Top 10:** A01:2021 – Broken Access Control

**Issue:**
- The `/users` endpoint exposes sensitive user data (names and emails) without any authentication
- No access control mechanisms in place
- No rate limiting or API key validation

**Risk:**
- Unauthorized users can access private user information
- No way to track who accessed the data
- Vulnerable to scraping and data harvesting

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommended Fix:**
```javascript
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized: No token provided' });
  }

  // Verify token (use JWT library like jsonwebtoken)
  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Forbidden: Invalid token' });
    }
    req.user = user;
    next();
  });
};

app.get('/users', authenticateToken, (req, res) => {
  // Only return users if authenticated
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 2. **MISSING INPUT VALIDATION & SANITIZATION** ⚠️ HIGH
**OWASP Top 10:** A03:2021 – Injection

**Issue:**
- No middleware to validate or sanitize incoming requests
- No validation of content-type headers
- No protection against malicious payloads
- Missing request body parsing limitations

**Risk:**
- Vulnerable to injection attacks (if routes are added that accept user input)
- NoSQL injection if database is added
- XSS if data is echoed back in responses
- Request bomb attacks

**Recommended Fix:**
```javascript
const express = require('express');
const helmet = require('helmet');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');

const app = express();

// Limit request size to prevent abuse
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// Validate content-type
app.use((req, res, next) => {
  if (req.method !== 'GET' && !req.is('application/json')) {
    return res.status(400).json({ error: 'Content-Type must be application/json' });
  }
  next();
});
```

---

### 3. **MISSING SECURITY HEADERS** ⚠️ HIGH
**OWASP Top 10:** A05:2021 – Security Misconfiguration

**Issue:**
- No Content Security Policy (CSP) headers
- No X-Frame-Options (clickjacking protection)
- No X-Content-Type-Options (MIME sniffing protection)
- No HSTS (HTTP Strict Transport Security)
- Missing CORS configuration

**Risk:**
- Clickjacking attacks
- MIME-sniffing attacks
- Man-in-the-middle attacks
- Uncontrolled cross-origin requests

**Recommended Fix:**
```javascript
const helmet = require('helmet');

// Add security headers using helmet
app.use(helmet());

// Additional HSTS configuration
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true
}));

// Configure CORS properly
const cors = require('cors');
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// CSP Headers
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));
```

---

### 4. **HARDCODED SENSITIVE DATA** ⚠️ HIGH
**OWASP Top 10:** A02:2021 – Cryptographic Failures

**Issue:**
- User email addresses are hardcoded in the source code
- No environment variable configuration
- No secrets management

**Risk:**
- Sensitive data exposed in version control
- Data visible in source code repositories
- No separation of configuration and code

**Recommended Fix:**
```javascript
require('dotenv').config(); // Load from .env file

// Store sensitive data in environment variables
const users = JSON.parse(process.env.USERS_DATA || '[]');

app.get('/users', authenticateToken, (req, res) => {
  res.json(users);
});
```

**.env file (never commit to version control):**
```
USERS_DATA=[{"id":1,"name":"Alice","email":"alice@example.com"},{"id":2,"name":"Bob","email":"bob@example.com"}]
JWT_SECRET=your-secure-secret-key-here
ALLOWED_ORIGINS=http://localhost:3000,https://yourdomain.com
```

**.gitignore:**
```
.env
.env.local
node_modules/
```

---

### 5. **MISSING RATE LIMITING** ⚠️ MEDIUM
**OWASP Top 10:** A05:2021 – Security Misconfiguration

**Issue:**
- No protection against brute force attacks
- No rate limiting on endpoints
- Vulnerable to DoS attacks

**Risk:**
- Attackers can bombard endpoints with requests
- Resource exhaustion
- Service unavailability

**Recommended Fix:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Limit each IP to 5 requests per windowMs
  skipSuccessfulRequests: true,
});

app.use(limiter); // Apply to all routes
app.post('/login', authLimiter, (req, res) => { /* ... */ });
```

---

### 6. **NO LOGGING & MONITORING** ⚠️ MEDIUM
**OWASP Top 10:** A09:2021 – Security Logging and Monitoring Failures

**Issue:**
- No request logging
- No error logging
- No security event tracking
- No audit trail

**Risk:**
- Cannot detect or investigate security incidents
- No visibility into attacks
- Compliance violations

**Recommended Fix:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// Setup logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Request logging
app.use(morgan('combined', { 
  stream: { write: (message) => logger.info(message) } 
}));

// Log security events
app.use((req, res, next) => {
  // Log suspicious patterns
  if (req.url.includes('admin') || req.url.includes('api')) {
    logger.info(`[SECURITY] Request to ${req.url} from ${req.ip}`);
  }
  next();
});

// Error logging
app.use((err, req, res, next) => {
  logger.error(`[ERROR] ${err.message}`, { 
    stack: err.stack, 
    url: req.url,
    method: req.method 
  });
  res.status(500).json({ error: 'Internal Server Error' });
});
```

---

### 7. **MISSING ERROR HANDLING & INFORMATION DISCLOSURE** ⚠️ MEDIUM
**OWASP Top 10:** A05:2021 – Security Misconfiguration

**Issue:**
- No centralized error handling
- Stack traces could leak sensitive information
- Default error messages are verbose

**Risk:**
- Information disclosure about system architecture
- Stack traces reveal file paths and dependencies
- Attackers can use error messages for reconnaissance

**Recommended Fix:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  logger.error(err);

  // Don't expose stack trace to client in production
  const isDevelopment = process.env.NODE_ENV === 'development';
  const message = isDevelopment ? err.message : 'An error occurred';
  const stack = isDevelopment ? err.stack : undefined;

  res.status(err.status || 500).json({
    error: message,
    ...(isDevelopment && { stack })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

---

### 8. **NO HTTPS/TLS ENFORCEMENT** ⚠️ HIGH
**OWASP Top 10:** A02:2021 – Cryptographic Failures

**Issue:**
- No enforcement of HTTPS
- Data transmitted in plain text possible
- No HSTS header

**Risk:**
- Man-in-the-middle attacks
- Credential interception
- Session hijacking

**Recommended Fix:**
```javascript
// Redirect HTTP to HTTPS
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// Use helmet.hsts() as shown above
app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true
}));
```

---

### 9. **NO DEPENDENCY SECURITY CHECKS** ⚠️ MEDIUM

**Issue:**
- No security audit of npm dependencies
- Vulnerable packages could be installed
- No lock file mentioned

**Risk:**
- Dependency vulnerabilities
- Supply chain attacks
- Compromised packages

**Recommended Fix:**
```bash
# Regular security audits
npm audit

# Fix vulnerabilities
npm audit fix

# Use npm audit in CI/CD
npm audit --audit-level=moderate

# Create package-lock.json
npm ci  # Use instead of npm install in production
```

**In package.json:**
```json
{
  "scripts": {
    "audit": "npm audit",
    "audit:fix": "npm audit fix",
    "start": "node app.js",
    "test": "jest"
  }
}
```

---

### 10. **MISSING ENVIRONMENT CONFIGURATION** ⚠️ MEDIUM

**Issue:**
- Port is hardcoded
- No NODE_ENV configuration
- No environment-specific settings

**Risk:**
- Cannot easily deploy to different environments
- Security settings cannot be adjusted per environment
- Configuration mistakes in production

**Recommended Fix:**
```javascript
require('dotenv').config();

const express = require('express');
const app = express();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;

if (NODE_ENV === 'production' && !JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable must be set in production');
}

// ... rest of app setup ...

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

---

## Recommended Secure Implementation

Here's a complete hardened version:

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const winston = require('winston');

const app = express();

// ============================================
// LOGGING SETUP
// ============================================
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ],
  ...(process.env.NODE_ENV !== 'production' && {
    transports: [
      ...this.transports,
      new winston.transports.Console({
        format: winston.format.simple()
      })
    ]
  })
});

// ============================================
// MIDDLEWARE: HTTPS REDIRECT
// ============================================
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// ============================================
// MIDDLEWARE: SECURITY HEADERS
// ============================================
app.use(helmet());
app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true
}));

// ============================================
// MIDDLEWARE: CORS
// ============================================
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// ============================================
// MIDDLEWARE: REQUEST PARSING & SANITIZATION
// ============================================
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));
app.use(mongoSanitize());
app.use(xss());

// ============================================
// MIDDLEWARE: LOGGING
// ============================================
app.use(morgan('combined', {
  stream: { write: (message) => logger.info(message) }
}));

// ============================================
// MIDDLEWARE: RATE LIMITING
// ============================================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ============================================
// MIDDLEWARE: AUTHENTICATION
// ============================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`[SECURITY] Missing auth token from ${req.ip}`);
    return res.status(401).json({ error: 'Unauthorized' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`[SECURITY] Invalid token from ${req.ip}`);
      return res.status(403).json({ error: 'Forbidden' });
    }
    req.user = user;
    next();
  });
};

// ============================================
// ROUTES
// ============================================
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticateToken, (req, res) => {
  try {
    const users = JSON.parse(process.env.USERS_DATA || '[]');
    logger.info(`[AUDIT] User list accessed by ${req.user.id}`);
    res.json(users);
  } catch (error) {
    logger.error(`[ERROR] Failed to fetch users: ${error.message}`);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// ============================================
// ERROR HANDLING
// ============================================
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

app.use((err, req, res, next) => {
  logger.error(`[ERROR] ${err.message}`, {
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  const isDevelopment = process.env.NODE_ENV === 'development';
  const message = isDevelopment ? err.message : 'An error occurred';

  res.status(err.status || 500).json({
    error: message,
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================
// SERVER STARTUP
// ============================================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

if (NODE_ENV === 'production' && !process.env.JWT_SECRET) {
  throw new Error('JWT_SECRET must be set in production');
}

app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

module.exports = app;
