# Node.js and Express Security: Vulnerabilities & Best Practices

## 1. Environment Variable Exposure

### Vulnerabilities

- **Hardcoded Secrets**: API keys, database credentials, and tokens stored directly in source code
- **Git History Exposure**: Secrets committed to version control and visible in repository history
- **.env Files in Version Control**: Configuration files containing sensitive data exposed publicly
- **Logs & Console Output**: Sensitive information printed to logs or console
- **Server Response Headers**: Environment details leaked through error messages or response headers

### Best Practices

```javascript
// GOOD: Use environment variables
require('dotenv').config();
const dbPassword = process.env.DB_PASSWORD;
const apiKey = process.env.API_KEY;

// GOOD: Validate required environment variables at startup
const requiredEnvVars = ['DB_PASSWORD', 'API_KEY', 'JWT_SECRET'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    throw new Error(`Missing required environment variable: ${envVar}`);
  }
});

// BAD: Hardcoded secrets
const apiKey = 'sk-1234567890abcdef'; // Never do this

// BAD: Logging sensitive data
console.log('User password:', userPassword); // Never log secrets
logger.info(`API Key: ${apiKey}`); // Never log secrets
```

### Implementation Steps

1. Create `.env` file locally (never commit to Git)
2. Add `.env` to `.gitignore`
3. Use environment-specific configuration files
4. Use a secrets management service (AWS Secrets Manager, HashiCorp Vault, etc.)
5. Rotate secrets regularly
6. Audit logs for exposed secrets
7. Use tools like `git-secrets` or `truffleHog` to detect leaks

---

## 2. Missing Security Headers

### Vulnerabilities

- **XSS (Cross-Site Scripting)**: Missing Content-Security-Policy headers
- **Clickjacking**: No X-Frame-Options header protection
- **MIME Type Sniffing**: Browser can misinterpret content types
- **SSL/TLS Stripping**: Missing HSTS enforcement
- **Information Disclosure**: Server version exposed in headers

### Best Practices

```javascript
const express = require('express');
const helmet = require('helmet');
const app = express();

// GOOD: Use Helmet middleware to set security headers
app.use(helmet());

// GOOD: Helmet sets these headers by default:
// - Content-Security-Policy: default-src 'self'
// - X-Frame-Options: DENY
// - X-Content-Type-Options: nosniff
// - X-XSS-Protection: 1; mode=block
// - Strict-Transport-Security: max-age=15552000; includeSubDomains

// GOOD: Customize security headers as needed
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'unsafe-inline'"], // Minimize unsafe-inline usage
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));

// GOOD: Strict HSTS policy (minimum 1 year)
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year in seconds
  includeSubDomains: true,
  preload: true,
}));

// BAD: Exposing server information
app.disable('x-powered-by'); // Already handled by Helmet

// GOOD: Explicitly disable server header
app.use((req, res, next) => {
  res.removeHeader('Server');
  next();
});
```

### Header Reference

| Header | Purpose | Recommended Value |
|--------|---------|-------------------|
| Content-Security-Policy | Prevents XSS attacks | `default-src 'self'; script-src 'self'` |
| X-Frame-Options | Prevents clickjacking | `DENY` or `SAMEORIGIN` |
| X-Content-Type-Options | Prevents MIME sniffing | `nosniff` |
| X-XSS-Protection | Legacy XSS protection | `1; mode=block` |
| Strict-Transport-Security | Enforces HTTPS | `max-age=31536000; includeSubDomains` |
| Referrer-Policy | Controls referer header | `strict-origin-when-cross-origin` |
| Permissions-Policy | Controls browser features | `geolocation=(), microphone=()` |

---

## 3. Input Validation

### Vulnerabilities

- **Type Coercion Attacks**: Unexpected data types causing logic errors
- **Buffer Overflow**: Overly large inputs
- **Null/Undefined Exploitation**: Missing null checks
- **Format String Attacks**: Unvalidated string formats
- **Prototype Pollution**: Malicious object properties

### Best Practices

```javascript
const express = require('express');
const { body, query, param, validationResult } = require('express-validator');
const app = express();

app.use(express.json({ limit: '10kb' })); // Limit payload size

// GOOD: Validate and sanitize all inputs
app.post('/api/users', [
  // Validate email
  body('email')
    .isEmail()
    .normalizeEmail()
    .trim(),

  // Validate password
  body('password')
    .isLength({ min: 8 })
    .matches(/[A-Z]/).withMessage('Password must contain uppercase')
    .matches(/[0-9]/).withMessage('Password must contain number'),

  // Validate name
  body('name')
    .trim()
    .escape() // Prevent XSS
    .isLength({ min: 1, max: 100 }),

  // Validate age
  body('age')
    .isInt({ min: 1, max: 150 }),

  // Handle validation errors
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
], (req, res) => {
  // req.body is validated and sanitized
  res.json({ message: 'User created' });
});

// GOOD: Validate query parameters
app.get('/api/posts', [
  query('page')
    .optional()
    .isInt({ min: 1 })
    .toInt(),

  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt(),

  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
], (req, res) => {
  // req.query is validated
  res.json({ data: [] });
});

// GOOD: Validate URL parameters
app.get('/api/users/:id', [
  param('id')
    .isMongoId() // if using MongoDB
    .or(param('id').isInt()),

  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  }
], (req, res) => {
  // req.params.id is validated
  res.json({ user: {} });
});

// BAD: No input validation
app.post('/api/bad', (req, res) => {
  const user = {
    email: req.body.email, // Could be anything
    age: req.body.age, // Could be negative or huge
    name: req.body.name, // Could contain malicious code
  };
});

// GOOD: Whitelist allowed properties
function filterUserInput(data) {
  const allowed = ['email', 'name', 'age'];
  return Object.keys(data)
    .filter(key => allowed.includes(key))
    .reduce((obj, key) => {
      obj[key] = data[key];
      return obj;
    }, {});
}

// GOOD: Prevent prototype pollution
function deepClone(obj) {
  if (obj === null || typeof obj !== 'object') return obj;
  if (obj.__proto__ !== Object.prototype) return obj; // Reject modified prototypes
  if (Array.isArray(obj)) return obj.map(deepClone);
  return Object.keys(obj).reduce((clone, key) => {
    if (key !== '__proto__' && key !== 'constructor' && key !== 'prototype') {
      clone[key] = deepClone(obj[key]);
    }
    return clone;
  }, {});
}
```

### Validation Libraries

- **express-validator**: Comprehensive validation and sanitization
- **joi**: Schema validation
- **yup**: Schema validation and transformation
- **validator.js**: String validation utilities

