## 4. SQL Injection & NoSQL Injection

### Vulnerabilities

- **String Concatenation**: Building queries with string concatenation
- **Dynamic Query Construction**: Unsanitized user input in queries
- **NoSQL Injection**: Malicious objects passed to NoSQL queries
- **Operator Injection**: Injecting MongoDB operators like `$ne`, `$or`

### Best Practices

```javascript
const express = require('express');
const mysql = require('mysql2/promise');
const mongoose = require('mongoose');
const app = express();

// ============================================
// SQL INJECTION PREVENTION (MySQL/PostgreSQL)
// ============================================

// BAD: String concatenation - VULNERABLE TO SQL INJECTION
app.get('/users/:email', async (req, res) => {
  const email = req.params.email;
  const query = `SELECT * FROM users WHERE email = '${email}'`;
  // Attacker could pass: ' OR '1'='1
  const result = await db.query(query);
  res.json(result);
});

// GOOD: Use parameterized queries / prepared statements
app.get('/users/:email', async (req, res) => {
  const email = req.params.email;
  const query = 'SELECT * FROM users WHERE email = ?';
  const [result] = await db.execute(query, [email]);
  res.json(result);
});

// GOOD: Using mysql2 with prepared statements
const connection = await mysql.createConnection({
  host: process.env.DB_HOST,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
});

app.post('/api/users', async (req, res) => {
  const { email, name } = req.body;
  const query = 'INSERT INTO users (email, name) VALUES (?, ?)';
  const [result] = await connection.execute(query, [email, name]);
  res.json({ id: result.insertId });
});

// ============================================
// NOSQL INJECTION PREVENTION (MongoDB)
// ============================================

// BAD: Direct query construction - VULNERABLE
app.get('/posts/:id', async (req, res) => {
  const id = req.params.id;
  // Attacker could pass: {"$ne": null} to bypass filtering
  const post = await Post.findOne({ _id: id });
  res.json(post);
});

// GOOD: Validate input type first
app.get('/posts/:id', async (req, res) => {
  const { id } = req.params;

  // Validate ID format
  if (!mongoose.Types.ObjectId.isValid(id)) {
    return res.status(400).json({ error: 'Invalid ID' });
  }

  const post = await Post.findOne({ _id: new mongoose.Types.ObjectId(id) });
  res.json(post);
});

// BAD: Directly using query parameters - VULNERABLE
app.get('/api/users', async (req, res) => {
  const filter = req.query; // Could contain {$where: "malicious code"}
  const users = await User.find(filter);
  res.json(users);
});

// GOOD: Whitelist allowed fields and validate
app.get('/api/users', async (req, res) => {
  const allowedFields = ['name', 'email', 'role'];
  const filter = {};

  for (const [key, value] of Object.entries(req.query)) {
    if (allowedFields.includes(key)) {
      // Ensure value is not an operator
      if (typeof value === 'string' && !value.startsWith('$')) {
        filter[key] = value;
      }
    }
  }

  const users = await User.find(filter);
  res.json(users);
});

// GOOD: Using schema validation with Mongoose
const userSchema = new mongoose.Schema({
  email: { type: String, required: true },
  name: { type: String, required: true },
  role: { type: String, enum: ['user', 'admin'], default: 'user' },
});

app.post('/api/users', async (req, res) => {
  try {
    // Mongoose schema validates and sanitizes
    const user = new User(req.body);
    await user.save();
    res.json(user);
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// GOOD: Use schema validation for queries
const userFilterSchema = new mongoose.Schema({
  email: String,
  role: { type: String, enum: ['user', 'admin'] },
});

app.get('/api/users', async (req, res) => {
  const { error, value } = await userFilterSchema.validate(req.query);
  if (error) {
    return res.status(400).json({ error: error.message });
  }

  const users = await User.find(value);
  res.json(users);
});

// ============================================
// GENERAL ORM/ODM SECURITY
// ============================================

// GOOD: Use ORM/ODM methods instead of raw queries
const users = await User.where('email').equals(email);
const posts = await Post.find({ userId: userId });

// BAD: Avoid eval() and similar functions
// NEVER use eval() or Function() constructor with user input
// eval(`db.query('${userInput}')`) // DANGEROUS

// GOOD: Use object methods for safe operations
app.post('/api/search', async (req, res) => {
  const { query, limit = 10 } = req.body;

  // Validate inputs
  if (typeof query !== 'string' || query.length > 500) {
    return res.status(400).json({ error: 'Invalid query' });
  }

  if (typeof limit !== 'number' || limit > 100) {
    return res.status(400).json({ error: 'Invalid limit' });
  }

  // Use safe query construction
  const results = await Post.find(
    { $text: { $search: query } },
    { score: { $meta: 'textScore' } }
  ).limit(limit);

  res.json(results);
});
```

### Key Principles

1. **Always use parameterized queries/prepared statements**
2. **Validate input types before querying**
3. **Whitelist allowed fields and operators**
4. **Use ORMs/ODMs with schema validation**
5. **Never concatenate user input into queries**
6. **Use principle of least privilege for database user**

