## 3. Authentication & Authorization Vulnerabilities

### Vulnerability Description
Weak authentication mechanisms or improper authorization checks allow attackers to impersonate users or access unauthorized resources.

### Examples

**Vulnerable Code:**
```javascript
// No password hashing
app.post('/register', (req, res) => {
  const user = {
    username: req.body.username,
    password: req.body.password // Stored in plaintext!
  };
  db.save(user);
});

// Missing authorization check
app.get('/user/:id/profile', (req, res) => {
  const profile = db.findUser(req.params.id);
  res.json(profile); // Anyone can access any profile!
});

// Weak JWT validation
const token = req.headers.authorization.split(' ')[1];
const decoded = jwt.decode(token); // No verification!
```

### Mitigation Strategies

**1. Password Hashing:**
```javascript
const bcrypt = require('bcrypt');

// Registration
app.post('/register', async (req, res) => {
  const hashedPassword = await bcrypt.hash(req.body.password, 10);
  const user = {
    username: req.body.username,
    password: hashedPassword
  };
  await db.save(user);
  res.status(201).json({ message: 'User created' });
});

// Login
app.post('/login', async (req, res) => {
  const user = await db.findOne({ username: req.body.username });
  const passwordMatch = await bcrypt.compare(req.body.password, user.password);
  if (passwordMatch) {
    // Generate token
  }
});
```

**2. JWT with Proper Validation:**
```javascript
const jwt = require('jsonwebtoken');

// Generate token
const token = jwt.sign(
  { userId: user.id, role: user.role },
  process.env.JWT_SECRET,
  { expiresIn: '1h', algorithm: 'HS256' }
);

// Verify token
const verifyToken = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'No token' });

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

app.get('/protected', verifyToken, (req, res) => {
  res.json({ data: 'protected' });
});
```

**3. Role-Based Access Control (RBAC):**
```javascript
const checkRole = (allowedRoles) => {
  return (req, res, next) => {
    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

app.delete('/user/:id', verifyToken, checkRole(['admin']), (req, res) => {
  // Only admins can delete users
  db.delete(req.params.id);
  res.json({ message: 'User deleted' });
});
```

**4. Multi-Factor Authentication (MFA):**
```javascript
const speakeasy = require('speakeasy');
const qrcode = require('qrcode');

// Setup 2FA
app.post('/setup-2fa', verifyToken, async (req, res) => {
  const secret = speakeasy.generateSecret({ 
    name: `App (${req.user.email})` 
  });
  const qr = await qrcode.toDataURL(secret.otpauth_url);
  res.json({ qr, secret: secret.base32 });
});

// Verify 2FA
const verifyOTP = (secret, token) => {
  return speakeasy.totp.verify({
    secret: secret,
    encoding: 'base32',
    token: token,
    window: 2
  });
};
```

