## 6. Rate Limiting & DDoS Protection

### Vulnerability Description
Without rate limiting, attackers can perform brute force attacks, credential stuffing, or DDoS attacks.

### Examples

**Vulnerable Code:**
```javascript
// No rate limiting - vulnerable to brute force
app.post('/login', (req, res) => {
  // Anyone can try unlimited login attempts
  authenticateUser(req.body);
});

// No API rate limiting - vulnerable to DDoS
app.get('/api/data', (req, res) => {
  // No protection against excessive requests
  res.json(fetchData());
});
```

### Mitigation Strategies

**1. Express Rate Limiter:**
```javascript
const rateLimit = require('express-rate-limit');

// General API rate limiter
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  skip: (req) => req.user?.isAdmin, // Skip rate limiting for admins
});

// Strict rate limiter for authentication
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 login attempts per 15 minutes
  skipSuccessfulRequests: true, // Don't count successful requests
  message: 'Too many login attempts, please try again later'
});

// Login endpoint
app.post('/login', authLimiter, (req, res) => {
  // Authentication logic
});

// API endpoints
app.get('/api/data', apiLimiter, (req, res) => {
  res.json({ data: 'protected' });
});
```

**2. Store Rate Limit Data in Redis (for distributed systems):**
```javascript
const RedisStore = require('rate-limit-redis');
const redis = require('redis');
const client = redis.createClient();

const limiter = rateLimit({
  store: new RedisStore({
    client: client,
    prefix: 'rl:' // rate limit prefix
  }),
  windowMs: 15 * 60 * 1000,
  max: 100
});

app.use('/api/', limiter);
```

**3. Implement CAPTCHA for Repeated Failures:**
```javascript
const reCaptcha = require('express-recaptcha').default;
const recaptcha = new reCaptcha(
  process.env.RECAPTCHA_SITE_KEY,
  process.env.RECAPTCHA_SECRET_KEY
);

app.get('/login', recaptcha.middleware.render, (req, res) => {
  res.render('login');
});

app.post('/login', recaptcha.middleware.verify, async (req, res) => {
  if (!req.recaptcha.data.score) {
    return res.status(400).json({ error: 'CAPTCHA verification failed' });
  }
  // Proceed with login
});
```

