## 8. Poor Error Handling & Information Disclosure

### Vulnerability Description
Verbose error messages or stack traces exposed to users can reveal sensitive system information useful for attacks.

### Examples

**Vulnerable Code:**
```javascript
// Exposes stack trace to client
app.get('/data', (req, res) => {
  try {
    const data = JSON.parse(req.body);
  } catch (err) {
    res.status(500).json({ error: err.stack }); // Dangerous!
  }
});

// Reveals database schema information
app.post('/login', async (req, res) => {
  try {
    const user = await User.findOne({ email: req.body.email });
  } catch (err) {
    res.status(500).json({ 
      error: 'Database error', 
      query: err.sql, // Exposes SQL query!
      details: err.message 
    });
  }
});
```

### Mitigation Strategies

**1. Generic Error Messages:**
```javascript
// Production error handler
app.use((err, req, res, next) => {
  console.error(err); // Log detailed errors server-side only

  if (process.env.NODE_ENV === 'production') {
    res.status(err.status || 500).json({
      error: 'An error occurred processing your request'
    });
  } else {
    res.status(err.status || 500).json({
      error: err.message,
      stack: err.stack // Only in development
    });
  }
});
```

**2. Structured Logging:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  res.status(500).json({ error: 'Internal Server Error' });
});
```

**3. Input Validation Error Messages:**
```javascript
const { body, validationResult } = require('express-validator');

app.post('/register', [
  body('email').isEmail().withMessage('Invalid email format'),
  body('password').isLength({ min: 8 }).withMessage('Password too short')
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array().map(e => ({
        field: e.param,
        message: e.msg  // Generic message, not system details
      }))
    });
  }
});
```

