## 10. Insufficient Logging & Monitoring

### Vulnerability Description
Without proper logging and monitoring, security incidents go undetected, and attackers can operate without discovery.

### Examples

**Vulnerable Code:**
```javascript
// No logging
app.post('/login', (req, res) => {
  // No record of who's attempting to login
  authenticateUser(req.body);
});

// Missing security event logging
app.delete('/user/:id', (req, res) => {
  // No audit trail for who deleted what
  db.delete(req.params.id);
});
```

### Mitigation Strategies

**1. Comprehensive Security Logging:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'security.log' }),
    new winston.transports.Console()
  ]
});

// Log authentication attempts
app.post('/login', async (req, res) => {
  const result = await authenticateUser(req.body);

  logger.info({
    event: 'login_attempt',
    username: req.body.username,
    success: result.success,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    timestamp: new Date()
  });

  if (!result.success) {
    logger.warn({
      event: 'failed_login',
      username: req.body.username,
      attempts: incrementAttempts(req.ip),
      ip: req.ip
    });
  }
});

// Log authorization failures
const checkAdmin = (req, res, next) => {
  if (req.user.role !== 'admin') {
    logger.warn({
      event: 'unauthorized_access_attempt',
      user: req.user.id,
      endpoint: req.path,
      role: req.user.role,
      ip: req.ip
    });
    return res.status(403).json({ error: 'Forbidden' });
  }
  next();
};

// Log data modifications
app.post('/data', (req, res) => {
  const id = db.save(req.body);

  logger.info({
    event: 'data_created',
    dataId: id,
    user: req.user.id,
    timestamp: new Date()
  });
});
```

**2. Real-Time Alerting:**
```javascript
const alerting = {
  checkSuspiciousActivity: (logs) => {
    const failedLogins = logs.filter(
      log => log.event === 'failed_login' 
        && log.timestamp > Date.now() - 5 * 60 * 1000 // Last 5 minutes
    );

    if (failedLogins.length > 5) {
      sendAlert({
        level: 'HIGH',
        message: `Multiple failed login attempts from ${failedLogins[0].ip}`,
        count: failedLogins.length
      });
    }
  }
};
```

